#!/usr/bin/env python3
"""Curated primary-source evidence table and audit narrative; references checked 2026-11-12."""
from pathlib import Path
import pandas as pd
R=Path(__file__).resolve().parent;O=R/'source_audit_results'
D='https://mmcif.pdb.org/dictionaries/mmcif_ma.dic/Items/_pdbx_SG_project.full_name_of_center.html'
T='https://zenodo.org/records/821654'
P='https://pmc.ncbi.nlm.nih.gov/articles/PMC11343611/'
rows=[
('JCSG','Joint Center for Structural Genomics','Structure-space coverage; genome and community targets; parallel homologs and constructs','Microexpression, production, purification and crystallization; recovered protocols are not a uniform soluble-yield assay','12 sampled IDs recovered; 8 exact trial-sequence matches; none of 6 negative records has explicit insolubility evidence','Multiple trials and protocol versions; four sampled target/trial sequence discrepancies','https://pmc.ncbi.nlm.nih.gov/articles/PMC2954196/'),
('MCSG','Midwest Center for Structural Genomics','Structural coverage and biological/community targets','Published small-scale soluble-fraction screening; construct-dependent scores','12 sampled IDs and exact trial sequences recovered; none of 6 negative records has explicit insolubility evidence; 2 positive records have soluble trial status','Different expression and purification protocols; some referenced expression text absent','https://pmc.ncbi.nlm.nih.gov/articles/PMC2792030/'),
('SECSG','Southeast Collaboratory for Structural Genomics','Program includes Pyrococcus furiosus and eukaryotic targets; selection and salvage','Protein expression, purification, X-ray/NMR pipeline','Published TargetTrack rule; record-level outcome not audited','Programme includes distinct organisms and production routes; prefix cannot assign an assay','https://pubmed.ncbi.nlm.nih.gov/16211508/'),
('SGPP','Structural Genomics of Pathogenic Protozoa Consortium','Trypanosomatid and malaria parasite protein structures','Production and crystallization pipeline; domain engineering','Published TargetTrack rule; record-level outcome not audited','Constructs/domains and protocols may differ; do not infer organism per row from project','https://pubmed.ncbi.nlm.nih.gov/18542886/'),
('NESG','Northeast Structural Genomics Consortium','Structural-genomics targets spanning organisms','Separate expression and solubility screens; codon-enhanced E. coli production','Published TargetTrack rule for SG headers; DNASU is a separate repository view','Centre and repository are not independent laboratories; no positive validation labels in this header stratum','https://pmc.ncbi.nlm.nih.gov/articles/PMC4110633/'),
('NYSGRC','New York Structural Genomics Research Consortium','Biological processes and protein-family classification for structure determination','Expression, purification, biophysical characterization and crystallization','Published TargetTrack rule; record-level outcome not audited','Do not silently equate NYSGRC with NYSGXRC; validation stratum is negative-only','https://pmc.ncbi.nlm.nih.gov/articles/PMC2373525/'),
('SSGCID','Seattle Structural Genomics Center for Infectious Disease','Pathogen-related targets; physical-property and redundancy filters','Cloning/expression and structure pipeline','Published TargetTrack rule; record-level outcome not audited','Selection already depends on size, composition and predicted membrane/complexity features','https://www.ssgcid.org/static/media/uploads/publications/PUBL_IDDT_REVIEW_19594426.pdf'),
('EFI','Enzyme Function Initiative','Functionally diverse enzyme superfamilies and unknown enzyme functions','Expression, purification, structure and functional characterization','Published TargetTrack rule; record-level outcome not audited','Functional-family selection can explain sequence/source predictability without technical contamination','https://pmc.ncbi.nlm.nih.gov/articles/PMC3238057/'),
('BSGC','Berkeley Structural Genomics Center','Minimal Mycoplasma proteomes; tractability and structural novelty; later deselection','Structure-production workflow','Published TargetTrack rule; record-level outcome not audited','Selection/deselection can stop a target for redundancy rather than insolubility','https://pubmed.ncbi.nlm.nih.gov/16276528/'),
('BSGI','Montreal-Kingston Bacterial Structural Genomics Initiative','Bacterial targets, including E. coli K-12/O157:H7 in programme literature','Structural genomics workflow','Published TargetTrack rule; record-level outcome not audited','Identity expansion established in wwPDB dictionary; assay context unlinked','https://journals.asm.org/doi/full/10.1128/jb.185.14.3994-4002.2003'),
('CESG','Center for Eukaryotic Structural Genomics','Eukaryotic structural novelty, biomedical relevance and predicted tractability','E. coli cell-based and wheat-germ cell-free platforms in programme literature','Published TargetTrack rule; record-level outcome not audited','UESolDS claims E. coli protocol selection, not that all centre experiments share a host','https://pmc.ncbi.nlm.nih.gov/articles/PMC2705709/'),
('MPP','Mitochondrial Protein Partnership','Mitochondrial protein programme; specific inclusion rules unrecovered','Structural biology programme; row assays unresolved','Published TargetTrack rule; record-level outcome not audited','Five training positives but 57 validation negatives: too little support for a binary within-centre model',D),
('PDB_serial','Header-derived PDB serial proxy','Published UESolDS construction selects deposited structures with E. coli expression host','Successful structure determination, not standardized soluble yield','Structure-selected positives; no negative class','Serial IDs do not retain a recoverable PDB accession map in these artifacts',P),
('DNASU_clone','Clone-ID proxy for DNASU plasmid repository','Published pET21_NESG/pET15_NESG subset','Repository retains explicit soluble status, expression status and vector/clone information','12/12 audited statuses agree with published labels; 0/12 exact matches to listed insert translation; 11 are insert plus LE','Status is stronger evidence, but assayed tag-bearing fusion, processed sequence and conditions need reconciliation','https://pmc.ncbi.nlm.nih.gov/articles/PMC3964992/'),
('RefSeq','Sequence-accession syntax; original experimental source unknown','Unknown; RefSeq identifier does not establish eSOL provenance','No linked measurement','All observed labels positive; experimental origin unverified','Do not treat this stratum as eSOL or native E. coli simply from its header','https://www.ncbi.nlm.nih.gov/refseq/'),
('TB_Rv','TB/Rv-style identifier proxy','Consistent with tuberculosis target naming; centre linkage not verified','Unknown for released records','No record-level outcome evidence recovered','Do not assign a centre, species or assay solely from Rv prefix',T),
('other','Residual header-proxy class','Contains ISFI, BIGS, NatPro and MSGP prefixes in this cohort','Mixed/unresolved','No record-level outcome evidence recovered','Retain original proxy; subprefix counts supplied rather than inventing homogeneous provenance',T),
('eSOL_unmapped','eSOL quantitative database; not a separately identified cohort source','E. coli gene library; cell-free translation','Soluble fraction after centrifugation, SDS-PAGE and autoradiography; separate chaperone conditions','Quantitative measurements exist; absence of a score is not a measured negative','No released-record-to-eSOL-assay/construct crosswalk recovered','https://dbarchive.biosciencedbc.jp/en/esol/data-1.html')]
for code,name in [('ISFI','Integrated Center for Structure and Function Innovation'),('BIGS','Bacterial targets at IGS-CNRS, France'),('NatPro','Enzyme Discovery for Natural Product Biosynthesis'),('MSGP','Marseilles Structural Genomics Program @ AFMB')]:
 rows.append(('other:'+code,name,'Programme identity in wwPDB controlled vocabulary; detailed selection unresolved','Row assays not recovered','Only a subprefix observation; no verified outcome','Do not silently replace frozen other source class or infer organism from programme name',D))
out=[]
for proxy,name,selection,measurement,evidence,unknown,url in rows:
 out.append(dict(source_proxy=proxy,programme_or_database=name,verified_programme_facts=selection,measurement_context=measurement,
                 record_level_evidence=evidence,reasonable_inference='Sampling/construct differences can induce biological source signatures; this does not establish a shortcut used for solubility',
                 unresolved=unknown,evidence_url=url,identity_caveat='Programme name is documented; header-to-original-record identity requires separate verification'))
pd.DataFrame(out).to_csv(O/'source_provenance.tsv',sep='\t',index=False)
lines=['# UESolDS source provenance and label validity — 2026-11-12','',
 '**Finding:** source restriction alone does not create a reliable binary solubility cohort. Original records are recoverable, but the audited structural-genomics negatives do not document measured insolubility. DNASU offers a more promising explicit-outcome route, with unresolved construct mapping.','',
 'This audit concerns the frozen 13,880 development proteins only. Source names below are the existing header-derived proxies; programme-level facts do not prove per-record origin, host or assay. Earlier reports and original labels remain unchanged.','',
 '## Published construction versus original measurements','',
 f'The [UESolDS paper]({P}) assigns TargetTrack negatives from early workflow stages (tested, selected, cloned, expression tested), and positives from expression/solubility/purification/structure progress. Work-stopped/other records were reportedly excluded. DNASU uses explicit Protein_Soluble versus Tested_Not_Soluble fields. eSOL is described as score-present versus score-absent; PDB E. coli-expression entries become positives. These are published construction rules, not recovered assay outcomes. Upstream filtering also removes negative sequences similar to positives, which can alter biological associations.','',
 'Missing expression, failed crystallization, unattempted expression and experimentally insoluble protein are different outcomes. Even successful expression does not quantify its soluble fraction. None should be silently recoded.','',
 'The [eSOL archive](https://dbarchive.biosciencedbc.jp/en/esol/data-1.html) reports 4,132 entries, of which 3,173 have solubility measurements, with distinct chaperone conditions. It measures soluble fraction after centrifugation in a cell-free system. This contradicts interpreting every missing value as measured insolubility; it does not identify which released UESolDS records originated there.','',
 '## Source-by-source evidence','',
 'The [machine-readable table](source_audit_results/source_provenance.tsv) separates programme facts, record evidence, inferences, uncertainties and primary references.','',
 '| Existing proxy | What it represents / selection | Record-level label evidence and unresolved issue |','|---|---|---|']
for proxy,name,selection,measurement,evidence,unknown,url in rows:
 lines.append(f'| {proxy} | [{name}]({url}). {selection}. | {evidence}. {unknown}. |')
lines += ['',
 'Programme selection can intentionally enrich families, organisms, lengths or tractable constructs. Such biological sampling is a valid explanation of sequence/source prediction, not automatically a laboratory artefact. The [PSI production-centre account](https://www.sciencedirect.com/science/article/pii/S0969212607004753) describes allocation of protein families between centres and sequence-based target selection. Thus centre and family are structurally associated upstream of any solubility assay.','',
 '## Direct TargetTrack recovery: fixed 24-record sample','',
 f'The [original TargetTrack archive]({T}) was downloaded outside the repository. Its published MD5 was verified (`200012a8a2a11ffd7e370ed142df36c3`). We scanned the complete XML and saved only the selected records and referenced protocols. The archive documents target sequences separately from trial sequences; a target can have multiple modified experimental constructs.','',
 'Sampling was prespecified: JCSG/MCSG × training/validation × label, with shortest, median-length and longest proteins in each cell (24 total, deterministic raw-ID tie breaks). This deliberately covers lengths and labels; **it is not a random prevalence estimate**. No record was selected by probe score.','',
 '- **24/24 IDs and exact target sequences recovered.** Exact trial sequences were recovered for 8/12 JCSG and 12/12 MCSG records. Four JCSG records differ from all available trial sequences.',
 '- **12 negative-labelled records:** nine have exact trial matches, whose histories contain only selection/cloning. The other three have matching target sequences but different trial constructs, also at early workflow stages. No explicit negative solubility measurement was recovered for any of the twelve. This does not prove those proteins are soluble; it means the negative label is not justified by a recovered measurement.',
 '- **12 positive-labelled records:** eleven have exact trial matches; five reach purification, including two MCSG records with an explicit soluble stage. Six show expression without a soluble stage; one JCSG target lacks an exact trial sequence. These evidence levels must remain distinct.',
 '- Multiple trials occur for the same exact sequence. One MCSG positive target has both stopped and successful trials. A single target-level maximum status discards condition-specific failures and successes.',
 '- Four sampled JCSG targets have current target status “work stopped,” despite their inclusion in the release. Trial statuses differ from aggregate target status. The released status field, snapshot and upstream selection implementation cannot be reconstructed just from the published description.','',
 'Evidence: [sample definition](source_audit_results/recovery_sample.tsv), [target matches](source_audit_results/targettrack_sample_matches.tsv), [all sampled trials](source_audit_results/targettrack_sample_trials.tsv), [XML snippets and protocols](source_audit_results/targettrack_sample/), [archive checksums](source_audit_results/targettrack_archive.json). All statuses are preserved literally; no missing measurement became a negative.','',
 '## Assay and construct comparability','',
 'The recovered archive contains 4 JCSG, 7 MCSG, 85 SECSG and 4 SGPP expression-protocol definitions (some text is missing). These are programme-wide definitions, not counts of protocols verified for this cohort; see [protocol counts](source_audit_results/targettrack_protocol_counts.tsv). A centre name cannot collapse these definitions into one assay.', '',
 'Recovered JCSG protocols distinguish expression from purification and describe changes in induction procedures over time. Recovered MCSG protocols include overnight 18°C induction and preparation of a soluble-fraction sample; other referenced expression protocol text is absent. Neither archive provides a uniform quantitative soluble-fraction result for the sampled negatives. The [MCSG vector study](https://pmc.ncbi.nlm.nih.gov/articles/PMC2792030/) directly demonstrates that fusion constructs can change solubility screening outcomes. This supports treating construct identity as part of the measurement, not stripping tags to “clean” the outcome.',
 'The published UESolDS E. coli-expression restriction does not make growth strain, vector, induction temperature, lysis, salt, detergent, cofactors, fusion partner or assay threshold identical. Same centre is therefore not same assay. Protein species must come from independent sequence/reference mapping, not the expression host.','',
 '## DNASU recovery pilot','',
 'A separate fixed sample covers three length-ranked records per split × label (12; six per label). All twelve clone pages were recovered and all twelve explicit soluble-status fields agree with the released labels. This is **stronger outcome evidence than a selected/cloned status**. However, none exactly matches the listed translated insert: eleven released sequences equal the listed insert plus C-terminal LE; the remaining pET15 record differs differently. The repository describes vector fusions, so an insert match would still not certify the assayed full fusion sequence.',
 'The [sample table](source_audit_results/dnasu_sample_matches.tsv) records statuses, vector, source, hashes and exact prefix/suffix differences. [Raw public pages](source_audit_results/dnasu_raw_pages.zip) preserve the retrieval. An initial feasibility lookup of clone 627866 is archived too but excluded from the prespecified twelve-sample counts. No tags were stripped and no labels were changed.',
 'This pilot supports prioritizing DNASU for recovery; it cannot certify all 460 DNASU-proxy records or establish one comparable assay. DNASU is a repository: its sampled pages name NESG as the contributing source, illustrating overlap between a repository proxy and a laboratory centre.','',
 '## Smallest practical resolution step','',
 'Recover the original assayed construct sequence, vector/tag layout, expression/solubility score and protocol/version for the six sampled DNASU negatives and six positives. Obtain the pre-cleaning sequence-to-clone crosswalk from UESolDS authors or the NESG/DNASU original assay records, and reconcile the terminal changes without modifying the frozen cohort. If this succeeds, audit all 51 DNASU negatives and the associated positive records (460 proteins total) under the same rule. This has clearer expected value than extracting more embeddings or choosing the best-performing centre.',
 'For JCSG/MCSG, a negative requires a recorded soluble-expression failure after detectable expression or a quantitative soluble-fraction result, with an exact assayed construct and protocol. Selection/cloning histories cannot supply that evidence. A new assay or a centre LIMS export may be necessary. No external messages were sent.','',
 '## Reproduction','',
 'Run `source_validity_audit.py --stage diversity` to create the fixed sample; `recover_targettrack_sample.py --xml /tmp/uesolds-source-audit/tt.xml.gz` to reproduce XML extraction; and `audit_dnasu_sample.py --pages source_audit_results/dnasu_raw_pages.zip` to reproduce the DNASU comparison. Commands are run from `curation/` with the existing pinned analysis environment. Reference bytes remain outside the repository except compact sample evidence.','']
(R/'SOURCE_AUDIT.md').write_text('\n'.join(lines))
